// a failed append can put every queue position and ticket back exactly as
// they were.
function collectExpiredWaiters(now) {
  const expired = [];
  while (deadlineQueue.size > 0) {
    const node = deadlineQueue.peek();
    if (node.dead) {
      // A dead node is structural garbage left by an earlier detach; a
      // release-all rollback never reattaches it, so just drop it here.
      deadlineQueue.pop();
      continue;
    }
    if (node.deadline > now) {
      break;
    }
    deadlineQueue.pop();
    const group = pendingGroups.get(node.requestId);
    if (group === undefined || group.deadlineNode !== node) {
      continue;
    }
    expired.push(group);
  }
  return expired;
