// its tickets, pushing the deadline nodes back in their original identities
// (a popped node cannot be unpops, so each gets a fresh-node identity,
// populated from the same record).
function reattachGroups(expired) {
  for (const group of expired) {
    const node = {
      requestId: group.requestId,
      deadline: group.deadline,
      tie: group.deadlineNode.tie,
