test('a folded release-all next to the unswapped full log is never counted twice', () => {
  const p = logPath('swap-crash');
  const c = fakeClock(0);
  const r = createRegistry({ ttlMs: 100, clock: c, logPath: p });
  const a = r.acquire('a', 'h', 40);
